private fun rewriterSteps(): List<CleanStep> {
        val out = ArrayList<CleanStep>()
        fun add(rule: TaintConfigurationItem, id: RuleOccurrenceId,
                positions: List<Pair<Int, Position>>, source: Boolean) {
            if (rule.info !is UserDefinedRuleInfo) return
            for ((actionOrdinal, p) in positions) for ((markOrdinal, m) in rule.resetMarks()) {
                val anyTarget = source && forms.pos(rule, p)?.any == true
                val action = if (anyTarget)
                    RemoveMark(RuleMark(m), (p as PositionWithAccess).base, TaintCleanReach.ExactAndAnyField)
                else RemoveMark(RuleMark(m), p, TaintCleanReach.Exact)
                out += forms.unconditional(rule, action, types,
                    ActionId(id, ActionRole.RETURN_REWRITER, actionOrdinal, markOrdinal))
            }
        }
        val sources = forms.rules.sourceRulesForMethod(callee, s, fact = null, allRelevant = true)
        for ((ordinal, rule) in sources.withIndex()) {
            val id = occurrence(RuleKind.REWRITER, rule.ruleOrdinal(ordinal))
            if (forms.valid(rule) && !forms.rewriteSourceOrSink(rule, rewriter, projectNegatives = false).isFalse)
                add(rule, id, rule.actionsAfter.mapIndexed { i, action -> rule.actionOrdinal(i) to action.position }, source = true)
        }
        val offset = sources.originalRuleCount()
        for ((ordinal, rule) in forms.rules.cleanerRulesForMethod(callee, s, fact = null, allRelevant = true).withIndex()) {
            val id = occurrence(RuleKind.REWRITER, offset + rule.ruleOrdinal(ordinal))
            if (forms.valid(rule) && rewriter.rewrite(rule.condition).isTrue)
                add(rule, id, rule.actionsAfter.mapIndexedNotNull { i, action ->
                    (action as? RemoveMark)?.let { rule.actionOrdinal(i) to it.position }
                }, source = false)
        }
        return out
    }

fun build(): CallPlan {
        val sinks = sinks()
        val (callees, models, unresolved) = resolve()
        val zeroCanReturn = unresolved || callees.isNotEmpty() || models.any { it.second.zeroCanReturn }
        val back = bindBack()
        val stages = buildList {
            add(Edges(BEFORE, BOUND, BIND_IN, bindIn()))
            for (sink in sinks) if (sink.endFacts.isNotEmpty())
                add(Edges(BOUND, REWRITTEN, END_FACTS, MicroEdgeBuilder().apply {
                    sink.endFacts.forEach { edge(it.edge) }
                }.buildStage(), Guard.SinkTriggered(sink)))
            add(Edges(BOUND, REWRITTEN, SOURCES, sources(sinks, zeroCanReturn)))
            add(Actions(BOUND, ADDED, cleanSteps()))
            if (callees.isNotEmpty()) add(Callees(ADDED, RETURNED, callees))
            for ((target, model) in models) add(Predefined(ADDED, RETURNED, target, model, model.compile(manager)))
            if (unresolved) {
                add(Edges(ADDED, RETURNED, UNRESOLVED, StatementSummary.identities(boundPositions())))
                add(Edges(ADDED, RETURNED, UNRESOLVED, passRules()))
            }
            if (callee.isConstructor && models.none { it.first === callee })
                add(Edges(ADDED, REWRITTEN, CONSTRUCTOR, StatementSummary.identities(boundPositions())))
            val rewriterSteps = rewriterSteps()
            add(if (forms.isRun1GroupView) Actions.run1GroupReturnRewriter(rewriterSteps, manager.marks)
                else Actions.run1FullReturnRewriter(rewriterSteps, manager.marks))
            add(Edges(REWRITTEN, AFTER, BIND_BACK, back))
            aliases(back)?.let { add(Edges(REWRITTEN, AFTER, ALIASES, it, Guard.MemoryEffect)) }
        }
        val staged = stages.mapIndexed { ordinal, stage ->
            if (stage !is Edges) stage else stage.copy(summary = stage.summary.withStaticOperations(
                stage.summary.staticOperations.map { operation ->
                    val id = operation.id.copy(stageOrdinal = ordinal)
                    when (operation) {
                        is StaticOperation.Read -> operation.copy(id = id)
                        is StaticOperation.Write -> operation.copy(id = id)
                        is StaticOperation.MarkInput -> operation.copy(id = id)
                    }
                }))
        }
        return CallPlan(touched(), staged, sinks, entry = BEFORE, exit = AFTER, passReads = passReads,
            zeroCanReturn = zeroCanReturn)
    }

override fun toVulnerabilities(report: Report): List<VulnerabilityWithTrace> {
        val counts = report.entries.groupingBy { it.state }.eachCount()
        logger.info { "Bidi analysis: ${counts[ReportState.CONFIRMED] ?: 0} CONFIRMED, ${counts[ReportState.DEMAND] ?: 0} DEMAND vulnerabilities" }
        return report.entries.map { entry ->
            val rule = entry.key.rule
            val witness = entry.witnesses.firstOrNull { it.confirmed } ?: entry.witnesses.first()
            val node = TaintSinkTracker.TaintVulnerabilityRuleNode.Unconditional(witness.methodKey)
            VulnerabilityWithTrace(TaintSinkTracker.TaintVulnerability(entry.key.statement, rule.id,
                hashMapOf(rule to node)), TracePathGenerationResult.Simple)
        }
    }

private inline fun tryResolveExitLocation(
            stmt: JMethodBoundaryInst,
            relevantLocations: List<List<IntermediateLocation>>?,
            isExit: (CommonInst) -> Boolean
        ): CommonInst? =
            relevantLocations?.firstOrNull()?.lastOrNull { isExit(it.inst) }?.inst
