override fun sinkRulesForMethodExit(
        method: CommonMethod,
        statement: CommonInst,
        fact: FactAp?,
        initialFacts: Set<InitialFactAp>?,
        allRelevant: Boolean
    ): Iterable<TaintMethodExitSink> {
        if (method !is JIRMethod || !method.isSpringControllerMethod()) {
            return base.sinkRulesForMethodExit(method, statement, fact, initialFacts, allRelevant)
        }

        val allBaseRules = base.sinkRulesForMethodExit(method, statement, fact, initialFacts = null, allRelevant)
        return allBaseRules.map { unfoldSpringExitObject(it) }
    }

fun TaintConfigurationItem.resetMarks(): List<Pair<Int, String>> {
    val marks = (info as? org.opentaint.dataflow.configuration.jvm.serialized.UserDefinedRuleInfo)
        ?.relevantTaintMarks.orEmpty()
    val selected = specialization?.resetMarkOrdinals
    return marks.mapIndexedNotNull { index, mark ->
        if (selected == null || index in selected) index to mark else null
    }
}

fun unconditional(rule: TaintConfigurationItem, a: Action, types: PositionTypeResolver,
                  actionId: ActionId? = null): List<CleanStep> = when (a) {
    is RemoveMark -> {
        val p = checkNotNull(pos(rule, a.position)) { "a rejected rule reaches the forms (§1.3): $rule" }
        val t = mark(a.mark)
        val reach = when {
            p.any -> CleanReach.BELOW
            a.reach == TaintCleanReach.Exact -> CleanReach.EXACT
            else -> CleanReach.AT_AND_BELOW
        }
        val bytes = stringBytes(p, types)
        listOfNotNull(Cleaner(p.base, node(p.path), reach, t),
            bytes?.let { Cleaner(p.base, node(p.path + it), reach, t) }).mapIndexed { substep, cl ->
            lowerCleaner(cl, types, actionId?.let { TemporaryKey(it, substep) })
        }
    }

